// Slated's platform-independent engine for Linux: a JavaScript port of SlatedCore (Swift).
//
// Pure ES module code: no `gi://` imports, no Node built-ins, no DOM. It must run unchanged in GJS
// (the GNOME Shell extension and its preferences), Node and JavaScriptCore (tests on macOS).
// Behavior is pinned to the Swift implementation by the golden vectors in /fixtures (generated by
// `swift run SlatedFixtures`, checked by linux/tests).
//
// Data shapes are plain objects matching Slated's config.json (see docs/CONFIG.md):
//
// @typedef {{x: number, y: number, width: number, height: number}} Rect
//   Top-left-origin global coordinates (y grows down), like Mutter's frame rects.
// @typedef {{displayID: number, name: string, frame: Rect, visibleFrame: Rect, isMain: boolean, scale: number}} ScreenInfo
//   `visibleFrame` excludes panels/docks (Mutter's work area). Screens are given in OS order.
// @typedef {Object} Action
//   Canonical JSON form, identical to Swift's Action encoding: {op: "move", x, y, width, height, screen?},
//   {op: "push", direction, style?, screen?}, {op: "by-orientation", landscape: Action, portrait: Action}, …
// @typedef {{key: string, modifiers: string[]}} KeyCombo
//   modifiers ⊆ ["ctrl", "alt", "shift", "cmd", "fn"]; "cmd" is Super on Linux. Config strings: "hyper+a".
// @typedef {{severity: "error"|"warning", message: string, file?: string, line?: number}} Diagnostic
// @typedef {{frame: Rect, screens: ScreenInfo[], settings?: Object<string, boolean|number|string>}} WindowContext
//
// Every function below is implemented in a sibling module and re-exported here; callers import only
// from this file.

export class SlatedError extends Error {
  /** @param {"invalidSyntax"|"invalidExpression"|"unknownOperation"|"screenNotFound"|"notImplemented"} kind */
  constructor(kind, message) {
    super(message);
    this.kind = kind;
  }
}

const notYet = (name) => () => {
  throw new SlatedError('notImplemented', `Not implemented yet: ${name}`);
};

// --- Expressions (Slate's expression language) ---------------------------------------------------
/** @type {(expression: string, variables: Object<string, number>) => number} */
export let evaluateExpression = notYet('evaluateExpression');

// --- Slate syntax ---------------------------------------------------------------------------------
/** "push left bar-resize:screenSizeX/2" → Action. Throws SlatedError. */
export let parseOperation = notYet('parseOperation');
/** Action → canonical Slate syntax (round-trips with parseOperation). */
export let formatOperation = notYet('formatOperation');
/** "a:ctrl,shift,alt,cmd" / "1:f4,ctrl,alt" → {keys: KeyCombo, modal: {keys: KeyCombo, toggle: boolean} | null} */
export let parseKeystroke = notYet('parseKeystroke');
/** Classic .slate text → {settings, bindings, layouts, defaults, diagnostics}; `options.readFile` for `source`. */
export let parseSlateConfig = notYet('parseSlateConfig');

// --- Window math ----------------------------------------------------------------------------------
/** Target frame for move/resize/push/nudge/throw/corner/by-orientation. Throws for other actions. */
export let targetFrame = notYet('targetFrame');
/** Origin once the window took `actualSize` (apps with minimum sizes). */
export let targetOrigin = notYet('targetOrigin');
/** The screen a Slate screen reference points to (null ref = the window's screen). */
export let resolveScreen = notYet('resolveScreen');

// --- Configuration (config.json) ------------------------------------------------------------------
/** JSON text (JSON5 comments/trailing commas allowed) → configuration with every default filled in. */
export let decodeConfiguration = notYet('decodeConfiguration');
/** Configuration → stable pretty JSON (sorted keys), as Swift writes it. */
export let encodeConfiguration = notYet('encodeConfiguration');
/** The author's Slate setup in native form (21 Hyper bindings), used on first run without a Slate config. */
export let starterConfiguration = notYet('starterConfiguration');

// --- Keys -----------------------------------------------------------------------------------------
/** "hyper+a" → KeyCombo (hyper = ctrl+alt+shift+cmd). Returns null if invalid. */
export let parseKeyCombo = notYet('parseKeyCombo');
/** KeyCombo → "hyper+a" (canonical config string). */
export let formatKeyCombo = notYet('formatKeyCombo');
/** KeyCombo → GNOME accelerator, e.g. "<Control><Alt><Shift><Super>a"; `hyperMode: "xkb"` maps hyper to "<Hyper>". */
export let toGnomeAccelerator = notYet('toGnomeAccelerator');

// --- Hotstrings -----------------------------------------------------------------------------------
/** new HotstringMatcher(hotstrings).feed(text, appId) → {hotstring, deleteCount, delimiter} | null */
export let HotstringMatcher = class {
  constructor() {
    throw new SlatedError('notImplemented', 'Not implemented yet: HotstringMatcher');
  }
};
/** "{date:yyyy-MM-dd}" etc. → expanded text. */
export let expandTemplate = notYet('expandTemplate');
